16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    public void setTelephone(String telephone) {
89	        this.telephone = telephone;
90	    }
91	
92	    public String getEmail() {
93	        return this.email;
94	    }
95	
96	    public void setEmail(String email) {
97	        this.email = email;
98	    }
99	
100	    public LocalDate getRegistrationDate() {
101	        return this.registrationDate;
102	    }
103	
104	    public void setRegistrationDate(LocalDate registrationDate) {
105	        this.registrationDate = registrationDate;
106	    }
107	
108	    public Integer getMembershipNumber() {
109	        return this.membershipNumber;
110	    }
111	
112	    public void setMembershipNumber(Integer membershipNumber) {
113	        this.membershipNumber = membershipNumber;
114	    }
115	
116	    public String getCustomerCode() {
117	        return this.customerCode;
118	    }
119	
120	    public void setCustomerCode(String customerCode) {
121	        this.customerCode = customerCode;
122	    }
123	
124	    protected Set<Pet> getPetsInternal() {
125	        if (this.pets == null) {
126	            this.pets = new HashSet<>();
127	        }
128	        return this.pets;
129	    }
130	
131	    protected void setPetsInternal(Set<Pet> pets) {
132	        this.pets = pets;
133	    }
134	
135	    public List<Pet> getPets() {
136	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
137	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
138	        return Collections.unmodifiableList(sortedPets);
139	    }
140	
141	    public void setPets(List<Pet> pets) {
142	        this.pets = new HashSet<>(pets);
143	    }
144	
145	    public void addPet(Pet pet) {
146	        getPetsInternal().add(pet);
147	        pet.setOwner(this);
148	    }
149	
150	    /**
151	     * Return the Pet with the given name, or null if none found for this Owner.
152	     *
153	     * @param name to test
154	     * @return true if pet name is already in use
155	     */
156	    public Pet getPet(String name) {
157	        return getPet(name, false);
158	    }
159	
160	    /**
161	     * Return the Pet with the given name, or null if none found for this Owner.
162	     *
163	     * @param name to test
164	     * @return true if pet name is already in use
165	     */
166	    public Pet getPet(String name, boolean ignoreNew) {
167	        name = name.toLowerCase();
168	        for (Pet pet : getPetsInternal()) {
169	            if (!ignoreNew || !pet.isNew()) {
170	                String compName = pet.getName();
171	                compName = compName.toLowerCase();
172	                if (compName.equals(name)) {
173	                    return pet;
174	                }
175	            }
176	        }
177	        return null;
178	    }
179	
180	    public Pet getPet(Integer petId) {
181	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
182	    }
183	
184	    @Override
185	    public String toString() {
186	        return new ToStringCreator(this)
187	
188	            .append("id", this.getId())
189	            .append("new", this.isNew())
190	            .append("lastName", this.getLastName())
191	            .append("firstName", this.getFirstName())
192	            .append("address", this.address)
193	            .append("city", this.city)
194	            .append("telephone", this.telephone)
195	            .toString();
196	    }
197	}
