17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        owner.setCity(canonicalCity(owner.getCity()));
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
113	            return new ResponseEntity<>(HttpStatus.CONFLICT);
114	        }
115	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
116	        owner.setCustomerCode(customerCode(owner));
117	        this.clinicService.saveOwner(owner);
118	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
119	        headers.setLocation(UriComponentsBuilder.newInstance()
120	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
121	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
127	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
128	        if (currentOwner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        currentOwner.setAddress(ownerFieldsDto.getAddress());
132	        currentOwner.setCity(ownerFieldsDto.getCity());
133	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
134	        currentOwner.setLastName(ownerFieldsDto.getLastName());
135	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
136	        this.clinicService.saveOwner(currentOwner);
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Transactional
142	    @Override
143	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        this.clinicService.deleteOwner(owner);
149	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
155	        Owner owner = this.clinicService.findOwnerById(ownerId);
156	        if (owner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        HttpHeaders headers = new HttpHeaders();
160	        Pet pet = petMapper.toPet(petFieldsDto);
161	        owner.setId(ownerId);
162	        pet.setOwner(owner);
163	        pet.getType().setName(null);
164	        this.clinicService.savePet(pet);
165	        PetDto petDto = petMapper.toPetDto(pet);
166	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
167	            .buildAndExpand(pet.getId()).toUri());
168	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
174	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
175	        if (currentOwner != null) {
176	            Pet currentPet = this.clinicService.findPetById(petId);
177	            if (currentPet != null) {
178	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
179	                currentPet.setName(petFieldsDto.getName());
180	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
181	                this.clinicService.savePet(currentPet);
182	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	            }
184	        }
185	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
191	        HttpHeaders headers = new HttpHeaders();
192	        Visit visit = visitMapper.toVisit(visitFieldsDto);
193	        Pet pet = new Pet();
194	        pet.setId(petId);
195	        visit.setPet(pet);
196	        this.clinicService.saveVisit(visit);
197	        VisitDto visitDto = visitMapper.toVisitDto(visit);
198	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
199	            .buildAndExpand(visit.getId()).toUri());
200	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
201	    }
202	
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
207	        Owner owner = this.clinicService.findOwnerById(ownerId);
208	        if (owner != null) {
209	            Pet pet = owner.getPet(petId);
210	            if (pet != null) {
211	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
212	            }
213	        }
214	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	    }
216	
217	    /**
218	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
219	     * owner using the same telephone number.
220	     *
221	     * @param owner the candidate owner to check
222	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
223	     */
224	    /**
225	     * Builds the customer code assigned to a newly created owner, formatted as
226	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
227	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
228	     *
229	     * @param owner the owner being created
230	     * @return the customer code for the owner
231	     */
232	    private String customerCode(Owner owner) {
233	        String city = owner.getCity();
234	        long existingInCity = this.clinicService.findAllOwners().stream()
235	            .filter(existing -> Objects.equals(existing.getCity(), city))
236	            .count();
237	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
238	    }
239	
240	    /**
241	     * Determines the canonical spelling of the city for a newly created owner. If another owner
242	     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
243	     * spelling of the city name is reused so that all owners in a city share a consistent value.
244	     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
245	     *
246	     * @param city the raw city as supplied when creating the owner, may be {@code null}
247	     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
248	     */
249	    private String canonicalCity(String city) {
250	        if (city == null) {
251	            return null;
252	        }
253	        String normalized = normalize(city);
254	        for (Owner existing : this.clinicService.findAllOwners()) {
255	            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
256	                return existing.getCity();
257	            }
258	        }
259	        return titleCase(city);
260	    }
261	
262	    /**
263	     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
264	     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
265	     * {@code "new  YORK city"} becomes {@code "New York City"}).
266	     *
267	     * @param value the value to title-case
268	     * @return the title-cased value
269	     */
270	    private static String titleCase(String value) {
271	        StringBuilder result = new StringBuilder();
272	        for (String word : value.strip().split("\\s+")) {
273	            if (word.isEmpty()) {
274	                continue;
275	            }
276	            if (result.length() > 0) {
277	                result.append(' ');
278	            }
279	            result.append(Character.toUpperCase(word.charAt(0)))
280	                .append(word.substring(1).toLowerCase(Locale.ROOT));
281	        }
282	        return result.toString();
283	    }
284	
285	    private boolean isDuplicateOwner(Owner owner) {
286	        return this.clinicService.findAllOwners().stream()
287	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
288	    }
289	
290	    /**
291	     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
292	     * any other non-digit characters). This is applied before storing the number and before the
293	     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
294	     * stored identically and treated as the same number.
295	     *
296	     * @param telephone the raw telephone number, may be {@code null}
297	     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
298	     */
299	    private static String normalizeTelephone(String telephone) {
300	        if (telephone == null) {
301	            return null;
302	        }
